            h_ranges.append((start, r - 1))
        start = r + 1
    if start < rows:
        h_ranges.append((start, rows - 1))

    # Create vertical segments (column ranges between walls)
    v_ranges = []
    start = 0
    for c in vwalls:
        if start < c:
